    ("tf",2,"r2-sang","Sangam literature was written in Tamil.",True,"True."),
    ("mcq",3,"r3-pall","The Pallavas built temples at","Mamallapuram",[("Delhi","Far in the north."),("Lothal","An Indus city.")],"The Shore Temple is there."),
    ("short",3,"r3-king","Name one of the three ancient Tamil kingdoms.",["chera","chola","pandya","cheras","cholas","pandyas"],"Muventar means three crowned kings."),
