    ("tf",2,"r2-pillar","The iron pillar of Delhi has rusted badly.",False,"False."),
    ("mcq",3,"r3-art","Gupta-age paintings are seen at","Ajanta",[("Lothal","An Indus city."),("Kanyakumari","A southern tip.")],"The Ajanta caves have fine paintings."),
    ("short",3,"r3-gold","The Gupta period is often called a",["golden age","golden age of india","the golden age"],"A time of creativity."),
